// src/app/nex-native/dev/theme-preview-generated/page.tsx
//
// NEX Theme Production · Phase A3 · dev-only generated-theme preview.
// --------------------------------------------------------------------------
// Owner-authorised 2026-10-19. Isolated from production rendering.
//
// Purpose:
//   Render a theme generated by the Phase A2 CLI (scripts/nex-themes)
//   through the real Standard Experience chat chrome · in a dev-only
//   route that NEVER touches the live LIVE_WORLD_PACKAGES registry or
//   the nex_chat_theme database table.
//
// How it works:
//   The CLI emits a `<slug>.package.json` sidecar next to each generated
//   `.package.ts`. This server component reads that JSON from the
//   repo-local `scripts/nex-themes/generated/<slug>/` directory and
//   hands it to the client fixture as a direct prop · no module import,
//   no registry mutation.
//
// Honesty invariants:
//   · Dev-gated. Returns 404 in production unless `NEX_DEV_ROUTES=1`.
//   · Reads ONLY from `scripts/nex-themes/generated/<slug>/`. Rejects
//     any slug containing `..`, `/`, `\`, or non-matching characters.
//   · Does NOT register the theme anywhere. Visiting this URL leaves
//     the LIVE_WORLD_PACKAGES map and the nex_chat_theme table
//     unchanged.
//   · Does NOT write analytics (trackThemeView) or session state.

import { notFound } from "next/navigation";
import { promises as fs } from "node:fs";
import * as path from "node:path";
import * as React from "react";
import { GeneratedPreviewClient } from "./_client";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const SLUG_RE = /^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/;

export default async function GeneratedThemePreviewPage({
  searchParams,
}: {
  searchParams: Promise<{ slug?: string; wallpaper?: string }>;
}): Promise<React.JSX.Element> {
  const isDev = process.env.NODE_ENV !== "production";
  const prodOverride = process.env.NEX_DEV_ROUTES === "1";
  if (!isDev && !prodOverride) notFound();

  const sp = await searchParams;
  const slug = (sp.slug ?? "").trim();
  if (!SLUG_RE.test(slug)) notFound();

  const projectRoot = path.resolve(process.cwd());
  const packageJsonPath = path.join(
    projectRoot,
    "scripts",
    "nex-themes",
    "generated",
    slug,
    `${slug}.package.json`,
  );

  let pkg: unknown;
  try {
    const text = await fs.readFile(packageJsonPath, "utf8");
    pkg = JSON.parse(text);
  } catch {
    notFound();
  }

  const wallpaperFallback: "theme-gradient" | "none" =
    sp.wallpaper === "off" ? "none" : "theme-gradient";

  return (
    <>
      <style>{`
        html, body { background: #020914 !important; color: #F4F7FC; margin: 0; }
        body { font-family: Inter, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif; }
      `}</style>
      <meta name="robots" content="noindex, nofollow" />
      <main
        data-nex-theme-preview-generated-root
        data-nex-theme-slug={slug}
        style={{
          minHeight: "100dvh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          padding: "20px 12px 40px",
          gap: 16,
        }}
      >
        <div style={{ maxWidth: 560, width: "100%" }}>
          <h1 style={{ margin: "0 0 4px", fontSize: 20, fontWeight: 700 }}>
            Generated theme preview · <code>{slug}</code>
          </h1>
          <p style={{ margin: 0, fontSize: 12, color: "#8BA9D1", lineHeight: 1.6 }}>
            Dev-only · reads <code>scripts/nex-themes/generated/{slug}/{slug}.package.json</code>.
            Not registered with LIVE_WORLD_PACKAGES. Not written to the DB.
          </p>
        </div>
        <div
          data-nex-theme-preview-stage
          style={{
            width: 390,
            height: 790,
            maxHeight: "calc(100dvh - 120px)",
            borderRadius: 32,
            overflow: "hidden",
            border: "1px solid rgba(0,175,255,0.35)",
            boxShadow: "0 20px 60px rgba(0,0,0,0.55)",
          }}
        >
          <GeneratedPreviewClient
            pkg={pkg as never}
            wallpaperFallback={wallpaperFallback}
          />
        </div>
      </main>
    </>
  );
}
